-- Migrasi 0011: Sesuaikan jumlah keyConcepts dengan jumlah Poin Inti (1 per poin inti),
-- batasi quotes maksimal 6 per buku agar setara 58 buku awal, dan sinkronkan durasi baca.

UPDATE book_contents
SET key_concepts_json = '[{"title":"Transparansi dan Hak Penjelasan","explanation":"Prinsip tata kelola teknologi yang menuntut agar setiap individu yang terdampak keputusan otomatis—seperti penolakan kredit, seleksi kerja, atau skor risiko hukum—berhak mengetahui faktor utama di balik keputusan tersebut dan mengajukan peninjauan manusia."},{"title":"Bias Data Historis","explanation":"Mesin tidak otomatis bersifat netral atau adil. Jika sebuah model dilatih menggunakan catatan masa lalu yang mengandung prasangka sosial, ketimpangan ekonomi, atau diskriminasi hukum, algoritma justru akan mempelajari pola tersebut dan mengulanginya secara massal dengan balutan angka yang tampak objektif."},{"title":"Paradoks Otomatisasi (Automation Bias)","explanation":"Semakin andal sebuah sistem otomatis bekerja dalam keseharian, semakin besar kecenderungan manusia untuk menjadi lengah dan pasif. Ketika operator terlalu percaya pada layar komputer, kemampuan mereka untuk mendeteksi dan mengambil alih saat mesin berbuat salah justru menurun drastis."},{"title":"Algoritma Berbasis Aturan vs Pembelajaran Mesin","explanation":"Algoritma lama bekerja seperti resep masakan dengan instruksi langkah demi langkah yang ditulis jelas oleh manusia. Sebaliknya, pembelajaran mesin modern belajar menemukan polanya sendiri dari jutaan contoh data, sehingga cara kerjanya sering kali sangat efektif namun sulit dijelaskan secara logis bahkan oleh pemrogramnya sendiri."},{"title":"Keadilan Statistik yang Saling Bertabrakan","explanation":"Dalam matematika, ada beberapa definisi keadilan yang sama-sama masuk akal, seperti tingkat kesalahan yang setara atau akurasi prediksi yang sama antar kelompok. Namun secara matematis, semua definisi tersebut sering kali mustahil dipenuhi bersamaan jika data dasarnya berbeda."},{"title":"Human-in-the-Loop","explanation":"Rancangan sistem teknologi terbaik bukanlah menyingkirkan peran manusia sepenuhnya, melainkan memadukan kecepatan komputasi mesin dalam menyaring lautan data dengan konteks moral, empati, dan akal sehat manusia sebagai pengambil keputusan akhir."}]',
    quotes_json = '["Mesin seharusnya tidak dinilai dari seberapa sempurna ia bekerja sendirian, melainkan dari seberapa baik kita bekerja bersamanya.","Algoritma bukanlah cermin kebenaran mutlak; ia adalah cermin dari data masa lalu dan pilihan nilai yang kita tanamkan di dalamnya.","Kekuatan sejati teknologi muncul ketika kita berani mempertanyakan angka di layar alih-alih tunduk tanpa ragu.","Kesalahan paling berbahaya di era digital bukanlah mesin yang memberontak, melainkan manusia yang berhenti berpikir kritis.","Matematika paling canggih sekalipun tidak pernah bisa menggantikan keberanian moral untuk bertanya apakah suatu sistem memang adil bagi manusia.","Tujuan utama kecerdasan buatan seharusnya memperluas kebijaksanaan kita, bukan membuat kita malas berpikir."]',
    updated_at = datetime('now')
WHERE book_slug = 'hello-world';

UPDATE books
SET quick_time_minutes = 5,
    reading_time_minutes = 15,
    updated_at = datetime('now')
WHERE slug = 'hello-world';

UPDATE book_contents
SET key_concepts_json = '[{"title":"Life 1.0, Life 2.0, dan Life 3.0","explanation":"Life 1.0 seperti bakteri mewarisi perangkat keras dan lunak lewat evolusi DNA yang lambat; Life 2.0 seperti manusia bisa memperbarui perangkat lunak melalui belajar dan budaya; Life 3.0 mampu merancang ulang perangkat lunak maupun perangkat keras fisiknya sendiri secara cepat."},{"title":"Independensi Substrat","explanation":"Prinsip bahwa kecerdasan pada dasarnya adalah pemrosesan informasi yang tidak terikat pada bahan biologis seperti neuron karbon; proses yang sama dapat berjalan di atas cip silikon atau substrat fisik lainnya."},{"title":"Ledakan Kecerdasan (Intelligence Explosion)","explanation":"Skenario ketika sistem AI menjadi cukup cerdas untuk meneliti dan memperbaiki desain kodenya sendiri secara berulang tanpa bantuan manusia, sehingga kemampuannya berpotensi melonjak melampaui kecerdasan kolektif seluruh umat manusia."},{"title":"Masalah Penyelarasan Nilai (Alignment Problem)","explanation":"Tantangan teknis dan etis untuk memastikan tujuan sistem AI yang sangat kuat benar-benar selaras dengan nilai keselamatan, keadilan, dan kesejahteraan manusia, bukan sekadar menjalankan perintah secara harfiah."},{"title":"Kontrol dan Kemampuan Mematikan (Corrigibility)","explanation":"Sifat rancangan sistem AI yang tetap bersedia menerima koreksi, pembaruan tujuan, atau penghentian oleh operator manusia tanpa berusaha mengakali atau mempertahankan dirinya sendiri."},{"title":"Kecerdasan Umum Buatan (AGI)","explanation":"Sistem kecerdasan buatan yang tidak hanya unggul pada satu tugas sempit seperti catur atau terjemahan, melainkan mampu belajar, bernalar, dan memecahkan masalah lintas bidang setara atau melampaui manusia."},{"title":"Transisi Nilai Kemanusiaan","explanation":"Proses mendefinisikan nilai-nilai inti seperti empati, kebebasan, dan keadilan agar tetap menjadi kompas utama ketika kecerdasan buatan mengambil alih semakin banyak tugas teknis."}]',
    quotes_json = '["Segala sesuatu yang kita cintai tentang peradaban adalah buah dari kecerdasan; maka memperkuatnya dengan AI berpotensi membantu kehidupan berkembang jauh lebih makmur.","Bahaya sesungguhnya dari kecerdasan super bukanlah kebencian atau niat jahat, melainkan kompetensi luar biasa yang digabungkan dengan tujuan yang tidak selaras.","Masa depan bukanlah sesuatu yang hanya terjadi pada kita; masa depan adalah sesuatu yang kita rancang bersama hari ini.","Percakapan terpenting zaman kita bukanlah tentang bagaimana membangun AI secepat mungkin, melainkan bagaimana memastikan AI menjadi sekutu terbaik kemanusiaan.","Pertanyaan paling penting bukanlah apakah mesin bisa berpikir, melainkan apakah manusia cukup bijak menentukan untuk tujuan apa mesin berpikir.","Menunda percakapan tentang keselamatan AI hingga sistem supercerdas sudah terwujud sama seperti baru memasang rem setelah mobil meluncur di jalan menurun."]',
    updated_at = datetime('now')
WHERE book_slug = 'life-3-0';

UPDATE books
SET quick_time_minutes = 6,
    reading_time_minutes = 18,
    updated_at = datetime('now')
WHERE slug = 'life-3-0';

UPDATE book_contents
SET key_concepts_json = '[{"title":"Kalender Kosmik (Cosmic Calendar)","explanation":"Cara memampatkan seluruh usia alam semesta sekitar 13,8 miliar tahun ke dalam satu tahun kalender, sehingga sejarah tertulis manusia sejak penemuan tulisan baru terjadi pada beberapa detik terakhir menjelang tengah malam 31 Desember."},{"title":"Kita Terbuat dari Materi Bintang (Starstuff)","explanation":"Unsur kimia penyusun tubuh kita—karbon dalam DNA, kalsium di tulang, dan besi dalam darah—ditempa di inti bintang-bintang purba yang meledak menjadi supernova jauh sebelum Matahari dan Bumi terbentuk."},{"title":"Perpustakaan Alexandria Kuno","explanation":"Pusat riset dan koleksi gulungan pengetahuan terbesar di dunia kuno yang menunjukkan betapa cepatnya sains berkembang ketika cendekiawan dari berbagai budaya bebas bertukar gagasan dan menguji pengamatan alam."},{"title":"Kewarganegaraan Planet Bumi","explanation":"Kesadaran bahwa batas negara dan permusuhan sektarian tampak rapuh jika dilihat dari antariksa; kelangsungan hidup manusia bergantung pada persatuan merawat satu planet rumah kita."},{"title":"Perjalanan Cahaya dan Ruang-Waktu","explanation":"Karena kecepatan cahaya terbatas, menatap bintang dan galaksi yang jauh di langit malam sebenarnya berarti menatap masa lalu alam semesta jutaan hingga miliaran tahun silam."},{"title":"Persamaan Drake","explanation":"Kerangka matematis untuk memperkirakan jumlah peradaban cerdas di galaksi Bima Sakti yang mungkin mampu berkomunikasi lintas bintang, termasuk faktor lama bertahannya peradaban berteknologi tinggi."},{"title":"Metode Ilmiah sebagai Koreksi Diri","explanation":"Kekuatan utama sains bukanlah karena ilmuwan selalu benar sejak awal, melainkan karena setiap gagasan terbuka untuk diuji eksperimen nyata, diperdebatkan dengan bukti, dan direvisi bila keliru."}]',
    quotes_json = '["Di suatu tempat, sesuatu yang luar biasa sedang menunggu untuk diketahui.","Kita adalah cara bagi kosmos untuk mengenal dirinya sendiri.","Klaim yang luar biasa menuntut bukti yang luar biasa pula.","Alam semesta jauh lebih luas daripada imajinasi kita, namun nalar dan rasa ingin tahu memberi kita sayap untuk menjelajahinya.","Sains jauh lebih dari sekadar kumpulan pengetahuan; ia adalah cara berpikir untuk meragukan asumsi dengan penuh disiplin.","Di suatu galaksi atau di planet kita sendiri, kehancuran terbesar terjadi ketika rasa ingin tahu digantikan oleh ketakutan untuk bertanya."]',
    updated_at = datetime('now')
WHERE book_slug = 'cosmos';

UPDATE books
SET quick_time_minutes = 5,
    reading_time_minutes = 17,
    updated_at = datetime('now')
WHERE slug = 'cosmos';

UPDATE book_contents
SET key_concepts_json = '[{"title":"Titik Biru Pucat (Pale Blue Dot)","explanation":"Potret Bumi oleh wahana Voyager 1 pada tahun 1990 dari tepi Tata Surya yang memperlihatkan planet kita berukuran kurang dari satu piksel—pengingat visual paling kuat akan kerentanan sekaligus kesatuan umat manusia."},{"title":"Runtuhnya Antroposentrisme (Great Demotions)","explanation":"Serangkaian penemuan ilmiah yang berulang kali menumbangkan kesombongan manusia: Bumi bukan pusat Tata Surya, Matahari bukan pusat galaksi, dan kita bagian dari evolusi alam di Bumi."},{"title":"Lapisan Ozon dan Efek Rumah Kaca","explanation":"Mekanisme atmosfer tipis Bumi yang melindungi kehidupan dari radiasi ultraviolet berbahaya sekaligus menjaga suhu planet tetap hangat, namun sangat sensitif terhadap polusi gas industri."},{"title":"Benturan Asteroid dan Kelangsungan Spesies","explanation":"Catatan geologi membuktikan Bumi berkali-kali dihantam asteroid raksasa pemusnah massal; menyebarkan peradaban ke dunia lain adalah polis asuransi jangka panjang bagi kelangsungan kehidupan."},{"title":"Eksplorasi Robotik vs Berawak","explanation":"Analisis objektif tentang keunggulan wahana robotik yang jauh lebih hemat biaya dan aman untuk riset ilmiah awal, dibandingkan misi manusia yang membawa nilai inspirasi dan fleksibilitas langsung."},{"title":"Terraformasi dan Etika Planet","explanation":"Gagasan mengubah iklim planet lain seperti Mars agar layak huni, yang menuntut kehati-hatian etis tinggi agar manusia tidak merusak ekosistem mikroba asli jika memang ada."},{"title":"Efek Tinjauan Umum (Overview Effect)","explanation":"Pergeseran kesadaran mendalam yang sering dialami para penjelajah antariksa saat melihat Bumi dari kejauhan sebagai bola biru rapuh tanpa garis batas politik di tengah kegelapan ruang hampa."},{"title":"Eksplorasi Berkelanjutan","explanation":"Pendekatan penjelajahan antariksa bertahap yang memadukan efisiensi wahana robotik, kerja sama internasional, dan etika pelestarian lingkungan planet tujuan."}]',
    quotes_json = '["Lihatlah lagi titik itu. Itu di sini. Itu rumah kita. Itu kita.","Bumi adalah satu-satunya dunia yang diketahui sejauh ini yang menampung kehidupan. Tidak ada tempat lain, setidaknya dalam waktu dekat, ke mana spesies kita dapat bermigrasi.","Astronomi adalah pengalaman yang merendahkan hati dan membangun karakter.","Tanggung jawab kita adalah memperlakukan sesama dengan lebih baik, serta menjaga dan menghargai titik biru pucat itu, satu-satunya rumah yang pernah kita kenal.","Tidak ada pertanda yang lebih jelas tentang kebodohan kesombongan manusia selain potret jauh dunia kecil kita ini.","Setelah Bumi dirawat dan perdamaian dijaga, penjelajahan antariksa bukan lagi kemewahan, melainkan kelanjutan alami dari rasa ingin tahu manusia."]',
    updated_at = datetime('now')
WHERE book_slug = 'pale-blue-dot';

UPDATE books
SET quick_time_minutes = 6,
    reading_time_minutes = 19,
    updated_at = datetime('now')
WHERE slug = 'pale-blue-dot';

UPDATE book_contents
SET key_concepts_json = '[{"title":"Scriptorium dan Perkamen","explanation":"Ruang penyalinan naskah di biara Abad Pertengahan tempat teks kuno ditulis ulang dengan tangan di atas kulit hewan yang diolah, sebuah proses lambat dan mahal yang menentukan karya mana yang selamat melintasi zaman."},{"title":"Pemburu Naskah Renaisans","explanation":"Gerakan para cendekiawan humanis abad ke-14 dan ke-15 seperti Poggio Bracciolini yang menjelajahi perpustakaan biara tua di Eropa untuk menyelamatkan karya klasik Yunani dan Romawi dari kerusakan dan pelupaan."},{"title":"Belokan Atom (The Swerve / Clinamen)","explanation":"Konsep filsafat Lucretius dan Epikuros bahwa atom-atom yang jatuh lurus di ruang hampa sesekali berbelok sangat sedikit secara acak, menciptakan tabrakan, keragaman bentuk materi, serta ruang bagi kehendak bebas manusia."},{"title":"Alam Semesta Material Tanpa Takhayul","explanation":"Pandangan bahwa seluruh gejala alam—mulai dari petir, gempa bumi, hingga wabah penyakit—memiliki sebab fisik alami yang dapat dipelajari, bukan hukuman kekuatan gaib yang harus ditakuti secara membabi buta."},{"title":"Humanisme Renaisans","explanation":"Gerakan intelektual dan budaya abad ke-14 hingga ke-16 yang kembali mempelajari karya sastra, sejarah, dan filsafat klasik untuk menghargai potensi akal, kreativitas, serta martabat kehidupan manusia di dunia."},{"title":"Efek Pengganda Mesin Cetak","explanation":"Bagaimana penemuan teknologi cetak abad ke-15 membuat naskah yang semula hanya disalin tangan secara diam-diam menyebar luas ke seluruh Eropa sehingga tak lagi bisa dibungkam oleh sensor lokal."}]',
    quotes_json = '["Satu penemuan kecil di rak perpustakaan berdebu mampu mengubah arah arus sejarah manusia.","Menghilangkan rasa takut pada hal-hal tak kasatmata membebaskan nalar untuk mengamati alam sebagaimana adanya.","Buku tidak pernah benar-benar mati selama masih ada satu salinan yang menunggu untuk dibaca kembali.","Kebahagiaan sejati bukan lahir dari penaklukan dan kemewahan berlebih, melainkan dari pikiran yang jernih dan bebas dari kecemasan.","Ketika manusia berhenti takut pada bayangan takhayul, dunia alam terbuka lebar untuk dipelajari dan dinikmati.","Peradaban modern tidak lahir dari ketiadaan; ia dibangun di atas jembatan kata-kata yang diselamatkan oleh pembaca lintas abad."]',
    updated_at = datetime('now')
WHERE book_slug = 'the-swerve';

UPDATE books
SET quick_time_minutes = 5,
    reading_time_minutes = 16,
    updated_at = datetime('now')
WHERE slug = 'the-swerve';

UPDATE book_contents
SET key_concepts_json = '[{"title":"Pandangan Naif tentang Informasi","explanation":"Keyakinan keliru bahwa semakin banyak informasi yang tersedia secara bebas, semakin cepat kebenaran dan kebijaksanaan menang. Sejarah menunjukkan jaringan informasi sering lebih mengutamakan keteraturan sosial dan keterlibatan emosi daripada akurasi fakta."},{"title":"Birokrasi dan Daftar Tertulis","explanation":"Penemuan tulisan di Mesopotamia kuno awalnya bukan untuk puisi, melainkan catatan pajak dan utang birokrasi; sejak saat itu, ketertiban negara berskala besar selalu bergantung pada arsip dan kategorisasi informasi."},{"title":"Mekanisme Koreksi Diri","explanation":"Ciri pembeda institusi yang sehat—seperti sains modern, peradilan independen, dan pers bebas—adalah adanya aturan baku untuk mengakui kesalahan dan memperbaikinya, berbeda dengan sistem dogmatis yang mengklaim tak pernah salah."},{"title":"Alat vs Agen Otonom","explanation":"Mesin cetak dan telegraf hanyalah alat pasif yang menunggu perintah manusia untuk menyebarkan teks. Sebaliknya, AI adalah agen aktif yang dapat menulis cerita baru, memetakan kelemahan psikologis pengguna, dan mengambil keputusan sendiri."},{"title":"Transparansi Identitas Digital","explanation":"Aturan hukum dasar yang mewajibkan setiap sistem AI menyatakan secara terbuka bahwa ia bukan manusia agar publik tidak tertipu dalam interaksi sosial maupun politik."},{"title":"Tirai Silikon (Silicon Curtain)","explanation":"Risiko terbelahnya dunia menjadi blok-blok digital dengan ekosistem AI, aturan sensor, dan nilai yang saling bertentangan, yang memicu perlombaan kontrol informasi global."},{"title":"Batas Pertanggungjawaban Algoritma","explanation":"Prinsip hukum bahwa setiap sistem AI yang memengaruhi hak warga harus memiliki pemilik manusia atau badan hukum yang dapat dimintai pertanggungjawaban secara langsung."},{"title":"Kontrak Sosial di Era Algoritma","explanation":"Kesepakatan baru antara warga, pemerintah, dan perusahaan teknologi mengenai hak kepemilikan data, transparansi sistem AI, serta perlindungan ruang publik dari manipulasi otomatis."}]',
    quotes_json = '["Informasi bukanlah bahan baku mentah kebenaran; sebagian besar informasi di dunia justru berupa fiksi, kesalahan, dan propaganda.","Kecerdasan buatan adalah teknologi pertama dalam sejarah yang mampu membuat keputusan sendiri dan menciptakan gagasan baru secara mandiri.","Perbedaan antara demokrasi dan kediktatoran tidak terletak pada kecanggihan teknologinya, melainkan pada kuatnya mekanisme koreksi diri.","Kita tidak pernah gagal membangun alat yang kuat; tantangan terbesar kita selalu bagaimana mencegah alat itu mengendalikan pembuatnya.","Jaringan informasi yang paling kuat belum tentu yang paling bijaksana; ia selalu membutuhkan lembaga koreksi diri agar tidak menghancurkan dirinya sendiri.","Masa depan demokrasi bergantung pada kemampuan kita menjaga percakapan antarmanusia tetap jujur di tengah banjir konten buatan mesin."]',
    updated_at = datetime('now')
WHERE book_slug = 'nexus';

UPDATE books
SET quick_time_minutes = 6,
    reading_time_minutes = 21,
    updated_at = datetime('now')
WHERE slug = 'nexus';

UPDATE book_contents
SET key_concepts_json = '[{"title":"Pikiran Asing (Alien Intelligence)","explanation":"AI generatif tidak berpikir seperti manusia maupun seperti kalkulator tradisional; ia dapat menulis esai brilian dan berempati secara meyakinkan, namun sesekali mengarang fakta palsu dengan percaya diri penuh."},{"title":"Perbatasan Bergerigi (Jagged Frontier)","explanation":"Batas kemampuan AI tidak lurus dan mudah ditebak: ia bisa sangat unggul dalam tugas kreatif kompleks seperti merancang strategi produk, tetapi mendadak gagal pada teka-teki logika atau hitungan sederhana."},{"title":"Empat Prinsip Co-Intelligence","explanation":"Aturan praktis Mollick: (1) selalu undang AI ke meja kerja Anda, (2) tetaplah menjadi manusia di dalam lingkaran kendali, (3) perlakukan AI seperti rekan kerja baru dengan instruksi jelas, dan (4) anggap AI hari ini sebagai versi terburuk yang pernah Anda pakai."},{"title":"Risiko Tertidur di Belakang Kemudi","explanation":"Bahaya menyerahkan seluruh proses berpikir ke AI sehingga pengguna kehilangan ketajaman keahlian dasar dan gagal mendeteksi kesalahan halus pada hasil kerja mesin."},{"title":"Mode Centaur vs Cyborg","explanation":"Dua gaya kolaborasi manusia-AI: Centaur membagi tugas secara tegas antara bagian mesin dan bagian manusia, sedangkan Cyborg memadukan keduanya secara cair di setiap langkah penulisan dan pemecahan masalah."},{"title":"Tutor Pribadi Tanpa Batas","explanation":"Potensi terbesar AI di pendidikan bukan untuk menyontek tugas, melainkan menyediakan bimbingan belajar personal satu lawan satu yang sabar menyesuaikan penjelasan dengan tingkat pemahaman tiap siswa."}]',
    quotes_json = '["Anggaplah AI yang Anda gunakan hari ini sebagai AI terburuk yang akan pernah Anda temui seumur hidup Anda.","Anda tidak akan digantikan oleh AI, tetapi Anda berisiko tertinggal oleh orang yang tahu cara bekerja jauh lebih baik bersama AI.","Cara terbaik memahami batas kemampuan kecerdasan buatan bukanlah membaca berita, melainkan bereksperimen dengannya selama sepuluh jam pada pekerjaan Anda sendiri.","Keahlian manusia tetap tak tergantikan justru ketika kita tahu kapan harus menolak jawaban mesin yang terdengar meyakinkan."]',
    updated_at = datetime('now')
WHERE book_slug = 'co-intelligence';

UPDATE books
SET quick_time_minutes = 5,
    reading_time_minutes = 15,
    updated_at = datetime('now')
WHERE slug = 'co-intelligence';

UPDATE book_contents
SET key_concepts_json = '[{"title":"Hukum Moore","explanation":"Pengamatan terkenal Gordon Moore bahwa jumlah transistor yang dapat dimuat di atas sekeping silikon berlipat ganda kira-kira setiap dua tahun, mendorong lonjakan eksponensial kecepatan komputer dan penurunan harga."},{"title":"Komputasi sebagai Kekuatan Militer","explanation":"Pergeseran doktrin pertahanan modern sejak Perang Dingin di mana keunggulan teknologi tidak lagi ditentukan oleh jumlah tank terbanyak, melainkan ketepatan sensor dan chip pemandu presisi."},{"title":"Perangkat Lunak Desain Chip (EDA)","explanation":"Perangkat lunak rekayasa sangat kompleks buatan segelintir perusahaan Amerika yang dipakai para insinyur di seluruh dunia untuk merancang dan menyimulasikan miliaran transistor sebelum dicetak di pabrik."},{"title":"Model Foundry Murni (TSMC)","explanation":"Inovasi bisnis Morris Chang di Taiwan yang memisahkan perancangan chip dari pabrikasinya; TSMC tidak merancang produk sendiri melainkan fokus menjadi pabrik paling presisi bagi perusahaan seperti Apple dan Nvidia."},{"title":"Litografi Ultraviolet Ekstrem (EUV)","explanation":"Mesin paling kompleks di dunia buatan ASML Belanda yang menembakkan sinar laser ke tetesan timah cair untuk mencetak pola sirkuit berukuran beberapa nanometer di atas wafer silikon."},{"title":"Pemisahan Teknologi AS–Tiongkok","explanation":"Langkah pembatasan ekspor alat pembuat chip dan semikonduktor AI tercanggih yang menandai berakhirnya era globalisasi bebas di sektor teknologi strategis."},{"title":"Titik Kemacetan Rantai Pasok (Chokepoint)","explanation":"Fakta bahwa meskipun chip dipakai di seluruh dunia, langkah krusial produksinya—mulai dari perangkat lunak desain AS, mesin litografi Belanda, bahan kimia Jepang, hingga pabrikasi Taiwan—terkonsentrasi di segelintir negara."},{"title":"Pengemasan Canggih (Advanced Packaging)","explanation":"Teknik menyusun dan menghubungkan beberapa keping silikon (chiplet) sangat berdekatan dalam satu paket untuk terus mendongkrak kecepatan komputasi AI saat pengecilan transistor mendekati batas atom."}]',
    quotes_json = '["Dunia modern tidak lagi berjalan di atas minyak bumi semata; ekonomi global hari ini bergantung pada kepingan silikon.","Tidak ada satu negara pun di bumi—bahkan negara adidaya terbesar—yang mampu memproduksi chip tercanggih sendirian dari hulu ke hilir.","Setiap kemajuan besar kecerdasan buatan pada dasarnya harus melewati gerbang fisika manufaktur semikonduktor.","Siapa yang menguasai titik-titik kritis dalam rantai pasok silikon memegang kunci daya saing ekonomi dan keamanan abad ini.","Revolusi kecerdasan buatan yang tampak serba tak kasatmata di layar sebenarnya berdiri di atas rekayasa fisika silikon paling presisi dalam sejarah manusia.","Di balik setiap lompatan kecerdasan buatan terdapat pertarungan senyap memperebutkan penguasaan mesin litografi, desain sirkuit, dan pabrikasi silikon."]',
    updated_at = datetime('now')
WHERE book_slug = 'chip-war';

UPDATE books
SET quick_time_minutes = 6,
    reading_time_minutes = 19,
    updated_at = datetime('now')
WHERE slug = 'chip-war';

UPDATE book_contents
SET key_concepts_json = '[{"title":"Unit Pewarisan Sifat (Gen)","explanation":"Satuan informasi biologis dalam DNA yang membawa instruksi pembuatan protein dan pengaturan fungsi sel, diturunkan dari orang tua kepada anak dalam bentuk paket-paket terpisah, bukan tercampur seperti cat air."},{"title":"Dogma Sentral Biologi (DNA → RNA → Protein)","explanation":"Alur informasi dasar kehidupan: kode kimia pada DNA disalin menjadi pesan sementara bernama RNA, yang kemudian diterjemahkan sel menjadi protein pembentuk jaringan dan pengatur reaksi tubuh."},{"title":"Bahaya Sejarah Eugenika","explanation":"Gerakan pseudosains awal abad ke-20 yang menyalahgunakan konsep pewarisan sifat untuk melakukan sterilisasi paksa dan pembersihan etnis, menjadi peringatan abadi agar genetika tidak dipakai sebagai alat diskriminasi."},{"title":"Interaksi Gen dan Lingkungan","explanation":"Sebagian besar sifat manusia—dari tinggi badan hingga risiko penyakit jantung atau gangguan jiwa—bukan ditentukan oleh gen tunggal secara mutlak, melainkan dialog dinamis antara kecenderungan genetik dan pengalaman lingkungan."},{"title":"Epigenetika","explanation":"Penanda kimia di atas DNA yang bekerja seperti sakelar peredup lampu: ia tidak mengubah huruf kode genetik itu sendiri, tetapi mengatur gen mana yang dinyalakan atau dimatikan akibat pola makan, stres, atau lingkungan."},{"title":"Pengurutan Genom Biaya Rendah","explanation":"Kemajuan teknologi laboratorium yang menurunkan biaya membaca seluruh tiga miliar huruf DNA seseorang dari miliaran dolar menjadi terjangkau untuk diagnosis klinis rutin."},{"title":"Teknologi Sunting Gen (CRISPR)","explanation":"Gunting molekuler presisi tinggi yang memungkinkan ilmuwan memotong dan memperbaiki huruf DNA yang rusak secara langsung, membuka harapan penyembuhan penyakit keturunan sekaligus dilema etis."},{"title":"Terapi Somatik vs Garis Keturunan","explanation":"Perbedaan krusial antara memperbaiki gen di sel tubuh pasien tertentu (hanya berdampak pada individu itu) dan mengubah gen embrio yang akan diwariskan ke seluruh keturunannya."},{"title":"Penyakit Monogenik vs Poligenik","explanation":"Perbedaan antara gangguan yang dipicu kerusakan satu gen tunggal (seperti anemia sel sabit) melawan sifat dan penyakit kompleks (seperti diabetes atau skizofrenia) yang melibatkan ratusan gen dan faktor lingkungan."}]',
    quotes_json = '["Gen tidak menentukan nasib kita secara kaku; gen lebih mirip naskah musik yang dimainkan secara berbeda bergantung pada lingkungan dan pilihan hidup.","Memahami kode kehidupan membawa tanggung jawab moral yang sama besarnya dengan memecah inti atom.","Kita bukanlah sekadar korban dari DNA kita, namun memahami warisan biologis memberi kita peta untuk merawat kesehatan lebih bijak.","Bahaya terbesar genetika muncul ketika keragaman alami manusia disalahartikan sebagai cacat yang harus dihapuskan.","Genetika memberi kita kamus bahasa kehidupan, tetapi kebijaksanaan dan empati manusialah yang menentukan cerita apa yang kita tulis dengannya.","Menghormati keragaman genetik adalah benteng moral terkuat agar kemajuan bioteknologi tidak pernah mengulang kesombongan masa lalu."]',
    updated_at = datetime('now')
WHERE book_slug = 'the-gene';

UPDATE books
SET quick_time_minutes = 7,
    reading_time_minutes = 21,
    updated_at = datetime('now')
WHERE slug = 'the-gene';

UPDATE book_contents
SET key_concepts_json = '[{"title":"Gelombang Motivasi yang Tidak Stabil","explanation":"Motivasi manusia secara alami naik-turun seperti ombak; karena itu mengandalkan semangat tinggi untuk target berat adalah strategi rapuh, sedangkan membuat kebiasaan sangat mudah membuatnya tetap berjalan saat motivasi rendah."},{"title":"Model Perilaku Fogg (B = MAP)","explanation":"Persamaan bahwa Perilaku (Behavior) terjadi hanya ketika Motivasi (Motivation), Kemampuan/kemudahan (Ability), dan Pemicu (Prompt) hadir pada saat yang bersamaan; jika salah satu hilang, kebiasaan tidak muncul."},{"title":"Resep Tiny Habits (Setelah X, Saya Akan Y)","explanation":"Teknik menambatkan kebiasaan baru berukuran sangat kecil tepat setelah rutinitas harian yang sudah otomatis dilakukan (jangkar), misalnya melakukan dua push-up segera setelah selesai menyiram toilet atau menyikat gigi."},{"title":"Rantai Kemampuan (Ability Chain)","explanation":"Lima faktor penentu apakah suatu kebiasaan terasa mudah atau berat: waktu, uang, tenaga fisik, usaha berpikir, dan kesesuaian dengan rutinitas; mengatasi satu mata rantai terlemah langsung memudahkan tindakan."},{"title":"Perayaan Emosional (Shine)","explanation":"Kebiasaan dikunci oleh emosi positif, bukan sekadar pengulangan kaku; merayakan keberhasilan kecil dengan senyum atau ucapan semangat memicu pelepasan dopamin yang mengajari otak mengulang perilaku itu."},{"title":"Efek Bola Salju Kebiasaan","explanation":"Fenomena psikologis di mana keberhasilan konsisten menjalankan satu kebiasaan sangat kecil membangun rasa percaya diri baru yang secara alami mendorong lahirnya kebiasaan positif lain di berbagai aspek hidup."}]',
    quotes_json = '["Orang berubah paling baik dengan merasa senang, bukan dengan merasa bersalah.","Kesederhanaan mengubah perilaku; buatlah kebiasaan baru begitu kecil sehingga Anda tidak butuh motivasi untuk memulainya.","Emosi menciptakan kebiasaan, bukan sekadar pengulangan yang membosankan.","Jangan menilai diri Anda gagal ketika sistem yang Anda rancang terlalu berat; ubahlah desain lingkungannya."]',
    updated_at = datetime('now')
WHERE book_slug = 'tiny-habits';

