SET quick_time_minutes = 5,
    reading_time_minutes = 16,
    updated_at = datetime('now')
WHERE slug = 'tiny-habits';

UPDATE book_contents
SET key_concepts_json = '[{"title":"Radiasi Latar Belakang Gelombang Mikro Kosmik (CMB)","explanation":"Cahaya sisa paling awal dari alam semesta yang baru berusia 380 ribu tahun, berfungsi sebagai foto bayi semesta yang membuktikan peristiwa Big Bang."},{"title":"Universalitas Hukum Fisika","explanation":"Prinsip ilmiah bahwa hukum fisika yang kita ukur di laboratorium Bumi—seperti gravitasi dan spektrum cahaya—berlaku identik di galaksi terjauh miliaran tahun cahaya."},{"title":"Materi Gelap (Dark Matter)","explanation":"Zat tak kasatmata yang tidak memancarkan maupun memantulkan cahaya, namun tarikan gravitasinya menjaga galaksi agar tidak tercerai-berai saat berputar cepat."},{"title":"Tabel Periodik Kosmik","explanation":"Pemahaman bahwa unsur-unsur kimia di tubuh dan gawai kita berasal dari beragam proses astrofisika: Big Bang, ledakan bintang masif, penggabungan bintang neutron, dan kematian bintang mirip Matahari."},{"title":"Perspektif Kosmik","explanation":"Cara memandang hidup dari ketinggian semesta yang meredam ego sempit manusia dan menumbuhkan rasa persaudaraan sesama penghuni Bumi."}]',
    quotes_json = '["Alam semesta tidak berkewajiban untuk masuk akal bagi intuisi Anda.","Kita bukan hanya berada di dalam alam semesta; alam semesta itu sendiri hidup di dalam diri kita.","Perspektif kosmik mengingatkan bahwa kita berasal dari debu bintang yang sama, namun sering kali bertengkar karena batas garis di peta.","Setiap atom besi di dalam darah Anda pernah berada di jantung bintang raksasa yang meledak miliaran tahun sebelum Bumi lahir.","Sains paling indah ketika ia membebaskan kita dari kesombongan dan menyatukan kita lewat rasa ingin tahu.","Tidak ada yang lebih melegakan pikiran selain menyadari bahwa masalah harian kita berlangsung di atas sebutir planet kecil yang mengitari bintang biasa."]',
    updated_at = datetime('now')
WHERE book_slug = 'astrophysics-for-people-in-a-hurry';

