UPDATE book_contents
SET key_concepts_json = '[{"title":"Relativitas Waktu dan Gravitasi","explanation":"Waktu tidak berdetak seragam di mana-mana; jam yang berada lebih dekat ke pusat gravitasi bumi atau bergerak lebih cepat berdetak sedikit lebih lambat dibandingkan jam di puncak gunung."},{"title":"Panah Waktu dan Entropi","explanation":"Satu-satunya hukum fisika dasar yang membedakan masa lalu dari masa depan adalah hukum kedua termodinamika: ketidakteraturan (entropi) sistem tertutup cenderung selalu bertambah."},{"title":"Ketiadaan ''Sekarang'' Universal","explanation":"Tidak ada momen ''saat ini'' tunggal yang serentak berlaku di Bumi dan di galaksi jauh; setiap tempat hanya memiliki jalinan waktu lokalnya masing-masing."},{"title":"Dunia Sebagai Peristiwa, Bukan Benda","explanation":"Alam semesta pada tingkat terdalam tidak tersusun dari benda-benda kaku yang diam, melainkan rangkaian peristiwa dan interaksi yang terus berubah seperti ciuman atau badai."},{"title":"Waktu yang Muncul dari Ketidaktahuan (Blurring)","explanation":"Aliran waktu yang kita alami bukan sifat dasar partikel tunggal, melainkan muncul dari pandangan makroskopis manusia yang tidak melihat gerakan detail seluruh atom."},{"title":"Ingatan sebagai Akar Pengalaman Waktu","explanation":"Otak manusia merangkai jejak masa lalu dalam memori dan mengantisipasi masa depan, sehingga rasa mengalirnya waktu lahir dari cara kesadaran kita membaca perubahan."}]',
    quotes_json = '["Dunia bukanlah kumpulan benda-benda; dunia adalah kumpulan peristiwa.","Perbedaan antara masa lalu dan masa depan tidak tertulis di hukum dasar partikel, melainkan lahir dari sudut pandang kita yang kabur terhadap alam.","Waktu adalah ukuran bagaimana kita mengalami perubahan melalui jejak ingatan dan harapan.","Fisika tidak membuktikan bahwa waktu yang kita alami itu palsu; ia menunjukkan bahwa aliran waktu adalah kisah indah dari sudut pandang manusia.","Mencintai kehidupan yang fana bukanlah keputusasaan, melainkan keberanian merayakan setiap detik yang tak terulang.","Waktu bukan musuh yang merampas hidup kita; ia adalah panggung tempat setiap pertemuan dan kenangan menjadi bermakna."]',
    updated_at = datetime('now')
WHERE book_slug = 'the-order-of-time';

