UPDATE book_contents
SET key_concepts_json = '[{"title":"Pernapasan Hidung vs Pernapasan Mulut","explanation":"Bernapas melalui hidung menyaring debu, menghangatkan udara, dan melepaskan oksida nitrat yang melebarkan pembuluh darah paru sehingga penyerapan oksigen jauh lebih efisien daripada bernapas lewat mulut."},{"title":"Evolusi Rahang Manusia Modern","explanation":"Perubahan pola makan modern ke makanan serba lunak mengurangi aktivitas mengunyah sejak kecil, membuat lengkung rahang menyempit, gigi berjejal, dan saluran napas atas lebih mudah tersumbat."},{"title":"Peran Karbon Dioksida (Efek Bohr)","explanation":"Oksigen di dalam darah baru dapat dilepaskan secara optimal ke sel otot dan otak apabila terdapat kadar karbon dioksida yang cukup; bernapas terlalu cepat justru menurunkan pelepasan oksigen ke jaringan."},{"title":"Pengosongan Paru-Paru Penuh","explanation":"Kapasitas paru-paru dan fungsi diafragma sangat dipengaruhi oleh seberapa tuntas kita mengembuskan udara lama keluar, bukan hanya seberapa keras kita menghirup udara baru."},{"title":"Napas Lambat dan Ritme Sempurna","explanation":"Pola bernapas sekitar 5,5 detik tarik dan 5,5 detik embus (~5,5 kali per menit) menyelaraskan detak jantung, tekanan darah, dan sistem saraf parasimpatis secara optimal."},{"title":"Toleransi Karbon Dioksida","explanation":"Sensitivitas otak terhadap kenaikan CO2 sering memicu rasa panik dan napas pendek; melatih toleransi CO2 dengan napas pelan dan tenang meningkatkan ketenangan dan daya tahan fisik."}]',
    quotes_json = '["Tidak ada gunanya makan sehat dan berolahraga rutin jika cara kita bernapas setiap menit keliru.","Hembusan napas yang penuh sama pentingnya dengan tarikan napas yang dalam, karena ia memberi ruang bagi udara segar berikutnya.","Napas yang sempurna berirama tenang: tarik selama lima setengah detik, embuskan selama lima setengah detik.","Hidung adalah organ pernapasan yang dirancang evolusi selama jutaan tahun; mulut seharusnya hanya menjadi cadangan darurat.","Mengubah cara Anda bernapas adalah tuas tercepat untuk mengubah kondisi sistem saraf Anda dalam hitungan detik.","Mengunyah makanan utuh dan menutup mulut saat tidur adalah investasi kesehatan termurah yang sering kita lupakan."]',
    updated_at = datetime('now')
WHERE book_slug = 'breath';

