UPDATE book_contents
SET key_concepts_json = '[{"title":"Utilitarianisme (Jeremy Bentham & J.S. Mill)","explanation":"Aliran etika yang menilai suatu tindakan benar apabila menghasilkan kebahagiaan terbesar dan penderitaan terkecil bagi jumlah orang terbanyak secara keseluruhan."},{"title":"Batas Moral Pasar (Moral Limits of Markets)","explanation":"Argumen Sandel bahwa tidak semua hal—seperti suara pemilu, donor organ, atau kehormatan warga—pantas diperjualbelikan karena uang dapat merusak nilai luhurnya."},{"title":"Imperatif Kategoris Immanuel Kant","explanation":"Prinsip moral bahwa manusia harus selalu diperlakukan sebagai tujuan pada dirinya sendiri yang bermartabat, bukan sekadar alat atau angka perhitungan untuk menguntungkan orang lain."},{"title":"Tabir Ketidaktahuan (John Rawls)","explanation":"Eksperimen pikiran untuk merancang masyarakat adil: bayangkan Anda membuat aturan sosial tanpa tahu apakah Anda kelak terlahir kaya, miskin, sehat, atau cacat."},{"title":"Etika Kebajikan Aristoteles","explanation":"Keyakinan bahwa keadilan tidak netral terhadap nilai moral; aturan hukum dan penghargaan sosial harus mempertimbangkan tujuan mulia suatu praktik serta karakter baik warganya."},{"title":"Kewajiban Solidaritas Komunitas","explanation":"Pandangan bahwa tanggung jawab moral kita tidak hanya berasal dari kontrak sukarela pribadi, melainkan juga dari ikatan sejarah, keluarga, dan kewarganegaraan bersama."}]',
    quotes_json = '["Belajar filsafat moral bukan soal menghafal jawaban baku, melainkan berani menguji keyakinan kita sendiri saat berhadapan dengan kasus sulit.","Masyarakat yang adil tidak cukup hanya menimbang berapa besar untung dan rugi; ia harus bertanya kehidupan bersama seperti apa yang ingin kita bangun.","Setiap manusia memiliki martabat yang tidak boleh ditukar hanya demi kenyamanan mayoritas.","Keadilan bukan sekadar soal memaksimalkan efisiensi ekonomi; ia adalah cermin nilai apa yang kita hormati sebagai manusia.","Masyarakat yang sehat tidak takut memperdebatkan perbedaan moral secara terbuka dan saling menghormati.","Filsafat dimulai ketika kita berani mempertanyakan kebiasaan yang selama ini kita anggap wajar tanpa pikir panjang."]',
    updated_at = datetime('now')
WHERE book_slug = 'justice';

UPDATE books
SET quick_time_minutes = 5,
    reading_time_minutes = 15,
    updated_at = datetime('now')
WHERE slug = 'justice';

UPDATE book_contents
SET key_concepts_json = '[{"title":"Lima Kepunahan Massal Sebelumnya","explanation":"Lima periode katastropik dalam sejarah geologi Bumi—termasuk kepunahan dinosaurus 66 juta tahun lalu—ketika sebagian besar spesies laut dan darat lenyap dalam waktu geologis singkat."},{"title":"Spesies Invasif Global","explanation":"Penyebaran cepat jamur, hama, dan predator lintas benua akibat pesawat dan kapal kargo modern yang melampaui penghalang samudra alami dan memusnahkan spesies lokal tanpa kekebalan."},{"title":"Pengasaman Laut (Ocean Acidification)","explanation":"Penurunan kadar pH air laut akibat menyerap miliaran ton karbon dioksida dari atmosfer, yang melarutkan kerangka kalsium karbonat terumbu karang, kerang, dan plankton dasar rantai makanan."},{"title":"Fragmentasi Habitat","explanation":"Pemecahan hutan dan ekosistem utuh menjadi pulau-pulau kecil terisolasi oleh jalan raya dan perkebunan, membuat satwa sulit bermigrasi mencari pasangan atau menyesuaikan diri saat iklim bergeser."},{"title":"Laju Kepunahan Latar Belakang vs Modern","explanation":"Perbandingan antara kepunahan alami yang sangat lambat pada masa geologi normal dengan laju hilangnya spesies saat ini yang ratusan hingga ribuan kali lebih cepat."},{"title":"De-Ekstingsi dan Biobank","explanation":"Upaya ilmiah membekukan sel hidup spesies langka sebagai cadangan genetik dan wacana menghidupkan kembali ciri spesies punah melalui rekayasa DNA."}]',
    quotes_json = '["Dalam sejarah geologi Bumi, tidak ada satu spesies tunggal pun yang pernah mengubah kimia atmosfer dan lautan secepat manusia.","Mengira kepunahan massal hanya terjadi akibat asteroid membuat kita lupa bahwa perubahan perlahan selama beberapa abad dapat berdampak sama dahsyatnya.","Melindungi keanekaragaman hayati berarti menjaga jaringan penopang hidup yang pada akhirnya juga menopang peradaban kita sendiri.","Lapisan batu bumi di masa depan akan mencatat kedatangan manusia sama jelasnya dengan lapisan abu tumbukan asteroid purba.","Melindungi spesies lain bukan sekadar kemurahan hati; itu adalah pengakuan bahwa kita bagian dari jaringan kehidupan yang sama.","Kecepatan perubahan yang dipicu manusia saat ini melampaui kemampuan jutaan spesies untuk berevolusi dan beradaptasi tepat waktu."]',
    updated_at = datetime('now')
WHERE book_slug = 'the-sixth-extinction';

UPDATE books
SET quick_time_minutes = 5,
    reading_time_minutes = 15,
    updated_at = datetime('now')
WHERE slug = 'the-sixth-extinction';

UPDATE book_contents
SET key_concepts_json = '[{"title":"Gelombang Kembar (AI & Biologi Sintetis)","explanation":"Konvergensi dua teknologi paling transformatif abad ini: AI yang mengotomatiskan kecerdasan dan biologi sintetis yang memungkinkan manusia memprogram DNA serta menciptakan molekul atau organisme baru."},{"title":"Jalur Sempit Pengendalian","explanation":"Sepuluh langkah berimbang—mulai dari audit keselamatan, pengawasan perangkat keras komputasi, penyaring pesanan DNA, hingga perjanjian internasional—untuk menjaga teknologi tetap aman."},{"title":"Sifat Asimetris dan Proliferasi","explanation":"Berbeda dengan senjata nuklir yang butuh bahan langka dan pabrik raksasa, model AI terbuka dan alat cetak DNA makin terjangkau sehingga individu atau kelompok kecil dapat memperoleh daya rusak besar."},{"title":"Negara Bangsa di Persimpangan Jalan","explanation":"Tekanan ganda pada pemerintah modern: serangan siber dan disinformasi AI menggerus kepercayaan publik sementara hilangnya pekerjaan menuntut kapasitas layanan sosial yang lebih kuat."},{"title":"Kecerdasan Kapabel Modern (ACI)","explanation":"Konsep Suleyman sebagai tolok ukur praktis menjelang AGI: sistem AI yang mampu menjalankan serangkaian tugas dunia nyata yang kompleks seperti merencanakan bisnis dan mengoordinasikan proyek."},{"title":"Tim Merah Independen (Red Teaming)","explanation":"Kelompok penguji keamanan eksternal yang sengaja mencoba membobol, memancing perilaku berbahaya, dan menemukan celah model AI sebelum diluncurkan ke publik."}]',
    quotes_json = '["Teknologi adalah pembesar kekuasaan terbesar yang pernah dimiliki manusia, tetapi ia tidak pernah otomatis menjamin kebijaksanaan pemakainya.","Menghadapi gelombang yang datang bukanlah soal memilih melarang segalanya atau menyerah tanpa aturan; kuncinya adalah merancang pengendalian yang cerdas.","Jika biaya menciptakan kekuatan besar turun mendekati nol, tanggung jawab keselamatan harus dibangun langsung ke dalam fondasi teknologinya.","Tugas generasi kita adalah berjalan di jalur sempit antara bencana penyalahgunaan dan tirani pengawasan.","Mengabaikan gelombang teknologi tidak akan menahannya, dan membiarkannya tanpa kendali sama seperti berlayar tanpa kemudi.","Keselamatan AI dan biosekuriti harus dibangun sebagai syarat dasar inovasi, bukan hiasan belakangan setelah krisis terjadi."]',
    updated_at = datetime('now')
WHERE book_slug = 'the-coming-wave';

