UPDATE book_contents
SET key_concepts_json = '[{"title":"Aturan Berhenti Optimal (37%)","explanation":"Solusi matematis untuk masalah pencarian berurutan: amati dan kumpulkan tolok ukur selama 37% awal peluang tanpa berkomitmen, lalu pilih kandidat pertama setelahnya yang lebih baik dari semua yang pernah Anda lihat."},{"title":"Eksplorasi vs Eksploitasi","explanation":"Dilema abadi antara mencoba hal baru yang belum pasti (eksplorasi) dan menikmati pilihan terbaik yang sudah dikenal (eksploitasi); jawabannya bergantung pada berapa banyak waktu tersisa di depan Anda."},{"title":"Cache Memori (LRU - Least Recently Used)","explanation":"Strategi menyimpan benda atau informasi yang paling baru dipakai di tempat paling mudah dijangkau—mirip tumpukan kertas di meja kerja yang sebenarnya sangat efisien bagi otak manusia."},{"title":"Penjadwalan Tugas Optimal","explanation":"Berbagai algoritma antrean komputer yang memberi panduan kapan mendahulukan tugas tercepat (Shortest Processing Time) dan kapan melindungi blok fokus panjang agar terhindar dari biaya pindah konteks."},{"title":"Bahaya Overfitting pada Prediksi","explanation":"Kesalahan menyusun rencana terlalu rumit berdasarkan kebetulan masa lalu; di dunia nyata yang penuh ketidakpastian, aturan sederhana justru sering mengalahkan model rumit."},{"title":"Komputasi Kebaikan (Computational Kindness)","explanation":"Prinsip merancang pilihan dan komunikasi sosial agar mengurangi beban berpikir orang lain—misalnya memberi opsi jadwal spesifik alih-alih pertanyaan terbuka yang melelahkan."}]',
    quotes_json = '["Ketika waktu tinggal sedikit, berhentilah bereksperimen dan nikmatilah hal-hal terbaik yang sudah Anda temukan.","Tumpukan dokumen yang tampak berantakan di meja kerja sebenarnya mengikuti prinsip cache paling efisien dalam ilmu komputer.","Kesempurnaan sering kali musuh dari keputusan tepat waktu; mengetahui kapan harus berhenti mencari adalah bentuk kebijaksanaan matematis.","Mengakui keterbatasan waktu dan ingatan membuat kita merancang strategi keputusan yang jauh lebih cerdas dan manusiawi.","Kesederhanaan aturan keputusan sering kali menjadi bentuk kecanggihan tertinggi di tengah dunia yang penuh ketidakpastian.","Di tengah dunia yang tidak pasti, kebijaksanaan sering kali berarti berani mengambil keputusan cukup baik tepat waktu alih-alih menunggu kepastian sempurna."]',
    updated_at = datetime('now')
WHERE book_slug = 'algorithms-to-live-by';

