UPDATE book_contents
SET key_concepts_json = '[{"title":"Domestikasi Diri Manusia (Homo Puppy)","explanation":"Hipotesis antropologi evolusioner bahwa selama puluhan ribu tahun manusia tanpa sadar menyeleksi sifat yang lebih ramah, kooperatif, dan tidak agresif, yang juga tecermin pada wajah lebih lembut dan kemampuan membaca gerak mata."},{"title":"Solidaritas Spontan Saat Krisis","explanation":"Temuan sosiologi bencana bahwa alih-alih panik dan menjarah, warga biasa hampir selalu membentuk jaringan tolong-menolong spontan saat menghadapi bencana."},{"title":"Kepatuhan yang Didesain (Milgram & Stanford)","explanation":"Temuan arsip baru yang mengungkap bahwa peserta eksperimen terkenal Milgram dan Penjara Stanford tidak bertindak kejam secara alami, melainkan ditekan, diarahkan, dan dimanipulasi oleh peneliti di balik layar."},{"title":"Otak Kolektif Sosial","explanation":"Gagasan antropologi bahwa kecerdasan unggul manusia berasal dari jaringan kerja sama dan saling belajar antarkelompok ramah, bukan dari kejeniusan individu yang terisolasi."},{"title":"Empati Sempit vs Welas Asih Universal","explanation":"Paradoks psikologi bahwa kasih sayang mendalam pada kelompok sendiri kadang bisa dimanipulasi pemimpin untuk memicu kebencian pada kelompok luar; kuncinya memperluas lingkaran kepedulian."},{"title":"Efek Plasebo vs Nosebo Sosial","explanation":"Ramalan yang terwujud dengan sendirinya: jika kita memperlakukan orang lain sebagai pemalas dan tak dapat dipercaya, mereka cenderung bersikap defensif dan sinis; jika kita memberi kepercayaan nyata, rasa tanggung jawab mereka tumbuh."},{"title":"Pemulihan Berbasis Martabat","explanation":"Pendekatan sistem pemasyarakatan yang berfokus pada pendidikan, keterampilan kerja, dan rehabilitasi sosial agar mantan narapidana kembali menjadi warga produktif."},{"title":"Realisme Pengharapan","explanation":"Sikap melihat manusia secara jujur: bukan naif menganggap semua orang malaikat, melainkan menyadari sebagian besar orang pada dasarnya ingin berbuat baik jika lingkungannya mendukung."}]',
    quotes_json = '["Menganggap manusia pada dasarnya baik bukanlah kenaifan romantis; bukti sejarah dan evolusi menunjukkan itulah cara spesies kita bertahan hidup.","Jika Anda mengasumsikan semua orang tidak jujur, Anda akan membangun sistem penuh birokrasi dan pengawasan yang justru mematikan inisiatif terbaik mereka.","Kebanyakan orang tidak menyakiti sesama karena kebencian alami, melainkan karena mereka diyakinkan bahwa mereka sedang membela orang-orang yang mereka cintai.","Realisme yang penuh harapan melihat dunia apa adanya tanpa kehilangan keyakinan pada kemampuan manusia untuk saling menjaga.","Kepercayaan yang diberikan kepada seseorang sering kali menjadi cermin tempat ia melihat potensi terbaik dirinya sendiri.","Keberanian terbesar di zaman yang sinis adalah tetap percaya pada kebaikan sesama manusia dan merancang institusi yang memuliakannya."]',
    updated_at = datetime('now')
WHERE book_slug = 'humankind';

