UPDATE book_contents
SET key_concepts_json = '[{"title":"Teknologi Pengubah Kesadaran: Tulisan & Kamus","explanation":"Lahirnya tulisan dan kamus cetak tidak sekadar merekam bahasa lisan, melainkan mengubah cara otak manusia mengingat, mengklasifikasikan, dan berpikir logis secara permanen."},{"title":"Universalitas Komputasi (Mesin Turing)","explanation":"Temuan Alan Turing bahwa satu mesin logika sederhana dengan aturan tepat mampu menyimulasikan perhitungan algoritma apa pun di alam semesta yang dapat dihitung."},{"title":"DNA sebagai Kode Informasi Biologis","explanation":"Pergeseran besar biologi abad ke-20 ketika gen dipahami bukan sebagai cairan misterius, melainkan instruksi digital empat huruf kimia yang disalin dan diterjemahkan sel hidup."},{"title":"Mesin Analitik Babbage & Ada Lovelace","explanation":"Visi abad ke-19 tentang mesin mekanik yang tidak hanya menghitung angka pajak, melainkan memanipulasi simbol umum seperti notasi musik dan logika—cikal bakal pemrograman komputer."},{"title":"Bit sebagai Satuan Dasar Informasi","explanation":"Temuan revolusioner Claude Shannon bahwa seluruh pesan—teks, suara, gambar, atau video—dapat diukur dan dikirim sebagai pilihan biner sederhana (0 atau 1) yang bebas dari makna semantiknya."},{"title":"Termodinamika Informasi (Prinsip Landauer)","explanation":"Penemuan fisika bahwa menghapus bit informasi secara permanen di komputer selalu melepaskan panas minimum tertentu, mengikat komputasi langsung pada hukum energi."},{"title":"Meme dan Replikasi Ide","explanation":"Konsep Richard Dawkins yang menafsirkan gagasan, lagu, dan budaya sebagai unit informasi yang bersaing memperebutkan perhatian otak manusia layaknya gen di alam."},{"title":"Perpustakaan Babel dan Masalah Kurasi","explanation":"Metafora sastra yang menggambarkan dunia penuh informasi tanpa penyaring: ketika segala kemungkinan teks tersedia serentak, nilai sejati berpindah ke kemampuan menyaring dan memverifikasi makna."}]',
    quotes_json = '["Informasi bukan sekadar kata-kata di atas kertas; ia adalah aliran darah yang menghubungkan fisika, biologi, dan kesadaran manusia.","Ketika alam semesta akhirnya memahami dirinya sendiri, ia melakukannya dengan menghitung bit informasi.","Di tengah banjir informasi yang tak berujung, hal paling langka dan paling berharga bukanlah data, melainkan perhatian manusia.","Setiap saluran komunikasi selalu memiliki kebisingan, namun kecerdikan kode memungkinkan kebenaran tetap sampai utuh ke tujuan.","Setiap lompatan besar komunikasi—dari tulisan hingga internet—selalu mengubah bukan hanya kecepatan pesan, tetapi juga bentuk pikiran manusia.","Di tengah lautan bit digital, kebijaksanaan lahir ketika kita berani berhenti sejenak untuk menyaring mana sinyal dan mana kebisingan."]',
    updated_at = datetime('now')
WHERE book_slug = 'the-information';

