UPDATE book_contents
SET key_concepts_json = '[{"title":"Persimpangan Seni dan Sains (Humaniora + Teknik)","explanation":"Kemajuan paling memikat—mulai dari visi Ada Lovelace hingga antarmuka grafis Macintosh—terjadi saat pemahaman puisi, desain visual, dan empati manusia bertemu dengan kecakapan rekayasa teknik."},{"title":"Pemrograman oleh Perintis Perempuan","explanation":"Pengakuan sejarah bahwa pada dekade awal komputer seperti ENIAC dan COBOL, perempuan seperti Grace Hopper dan tim enam pemrogram ENIAC memegang peran kunci mendefinisikan dunia perangkat lunak."},{"title":"Pengujian Terbuka Request for Comments (RFC)","explanation":"Tradisi kolaborasi teknis awal internet di mana setiap rancangan protokol dipublikasikan terbuka untuk dikritik dan disempurnakan oleh komunitas insinyur."},{"title":"Komputer Sebagai Mitra Simbiosis Manusia","explanation":"Visi J.C.R. Licklider dan Douglas Engelbart pada era 1960-an bahwa komputer seharusnya tidak menggantikan manusia, melainkan memperluas daya pikir dan kolaborasi tim (augmenting human intellect)."},{"title":"Arsitektur Terbuka Internet (Packet Switching)","explanation":"Rancangan jaringan tanpa pusat tunggal yang memecah pesan menjadi paket-paket kecil dan merutekannya ulang secara otomatis jika satu jalur terputus—fondasi ketangguhan internet dan World Wide Web."},{"title":"Pasangan Kolaboratif Saling Melengkapi","explanation":"Pola historis di balik banyak perusahaan dan penemuan besar—seperti Wozniak & Jobs, Gates & Allen, Page & Brin—di mana visi produk berpadu dengan ketajaman rekayasa."},{"title":"Protokol Terbuka Tanpa Royalti","explanation":"Keputusan perintis TCP/IP dan World Wide Web untuk membagikan standar dasar secara gratis kepada dunia, yang memicu ledakan inovasi massal di atasnya."},{"title":"Ketekunan Eksekusi di Balik Visi","explanation":"Pelajaran bahwa gagasan brilian hanya mengubah dunia apabila dipadukan dengan rekayasa disiplin, pengujian berulang, dan desain yang ramah pengguna biasa."},{"title":"Inovasi Sebagai Olahraga Tim","explanation":"Temuan utama Isaacson bahwa hampir semua terobosan era digital lahir bukan dari jenius penyendiri di loteng, melainkan pasangan kolaboratif dan tim beragam yang saling melengkapi kelemahan masing-masing."}]',
    quotes_json = '["Kreativitas sejati adalah usaha kolaboratif; inovasi jarang lahir dari satu pikiran tunggal yang terisolasi.","Perangkat lunak yang paling menyentuh hidup jutaan orang lahir di persimpangan antara logika teknik yang presisi dan kepekaan seni kemanusiaan.","Penghargaan terhadap sejarah para perintis mengajarkan bahwa berbagi ide secara terbuka hampir selalu melaju lebih cepat daripada menyimpannya rapat-rapat sendirian.","Masa depan komputasi terbaik bukanlah kecerdasan buatan yang berjalan sendirian, melainkan simbiosis yang memperkuat kecerdasan manusia.","Sejarah era digital bukan kisah tentang satu pahlawan tunggal di garasi, melainkan simfoni ribuan kolaborator lintas generasi.","Inovasi paling bertahan lama terjadi saat teknologi canggih dirancang dengan empati mendalam terhadap cara manusia hidup dan bekerja."]',
    updated_at = datetime('now')
WHERE book_slug = 'the-innovators';

